// A human operator selects one reviewed dead-letter ID before manual execution.
// This avoids an unauthenticated mutation webhook and prevents automatic bulk retry.
const TARGET_DEAD_LETTER_ID = 'CONFIGURE_DEAD_LETTER_ID';

return [{
  json: {
    reprocessing_request: {
      dead_letter_id: TARGET_DEAD_LETTER_ID,
      requested_at: new Date().toISOString(),
      requested_by: 'manual_operator',
      dry_run: false,
    },
  },
}];

const request = $('Select Reprocessing Target').first().json;
return $input.all().map((item) => {
  if (!item.json?.dead_letter_id) throw new Error(`Dead letter not found: ${request.reprocessing_request.dead_letter_id}`);
  return { json: { ...request, dead_letter: item.json } };
});

const context = $('Attach Reprocessing Dead Letter').first().json;
return $input.all().map((item) => ({
  json: {
    ...context,
    inquiry: item.json?.inquiry_id ? item.json : null,
    inquiry_found: Boolean(item.json?.inquiry_id),
  },
}));

return $input.all().map((item) => {
  const data = item.json;
  const dlq = data.dead_letter;
  const reasons = [];
  const retryableCategories = new Set(['transient_network', 'rate_limit', 'provider_communication']);

  if (dlq.status !== 'open') reasons.push('dead_letter_not_open');
  if (Number(dlq.attempt_count ?? 0) >= 3) reasons.push('attempt_limit_reached');
  if (!retryableCategories.has(dlq.error_category)) reasons.push('non_retryable_category');
  if (!data.inquiry_found) reasons.push('inquiry_not_found');
  if (!dlq.original_payload_json || dlq.original_payload_json === '{}') reasons.push('original_payload_missing');

  let recoveryBoundary = 'manual_only';
  if (reasons.length === 0) {
    if (dlq.error_stage === 'communication') recoveryBoundary = 'communication_only';
    else if (dlq.error_stage === 'followup') recoveryBoundary = 'followup_only';
    else if (dlq.error_stage === 'crm') recoveryBoundary = 'crm_reconcile';
    else reasons.push('unsupported_automatic_stage');
  }

  const approved = reasons.length === 0 && recoveryBoundary !== 'manual_only';
  return { json: { ...data, recovery: {
    decision: approved ? 'approved' : 'manual_only',
    approved,
    recovery_boundary: recoveryBoundary,
    reasons,
    dry_run: data.reprocessing_request.dry_run,
    attempt_number: Number(dlq.attempt_count ?? 0) + 1,
  } } };
});

return $input.all().map((item) => ({ json: {
  status: 'manual_review_required',
  dead_letter_id: item.json.dead_letter.dead_letter_id,
  inquiry_id: item.json.dead_letter.inquiry_id || null,
  error_stage: item.json.dead_letter.error_stage,
  error_category: item.json.dead_letter.error_category,
  recovery_boundary: item.json.recovery.recovery_boundary,
  reasons: item.json.recovery.reasons,
  message: 'No automatic retry was attempted. Fix or review the underlying condition first.',
} }));

return $input.all().map((item) => ({ json: {
  status: 'approved_dry_run',
  dead_letter_id: item.json.dead_letter.dead_letter_id,
  inquiry_id: item.json.dead_letter.inquiry_id,
  recovery_boundary: item.json.recovery.recovery_boundary,
  attempt_number: item.json.recovery.attempt_number,
  message: 'Safety checks passed. No record was claimed and no provider action was attempted.',
} }));

return $input.all().map((item) => ({ json: {
  ...item.json,
  claim: {
    previous_attempt_count: Number(item.json.dead_letter.attempt_count ?? 0),
    attempt_count: Number(item.json.dead_letter.attempt_count ?? 0) + 1,
    claimed_at: new Date().toISOString(),
    status: 'retrying',
  },
} }));

const originals = $('Prepare Retry Claim').all();
return $input.all().map((item, index) => {
  const original = originals[index]?.json;
  if (!original) throw new Error(`Missing retry-claim context ${index}`);
  const acquired = item.json?.dead_letter_id === original.dead_letter.dead_letter_id;
  return { json: { ...original, claim: { ...original.claim,
    acquired,
    result: acquired ? 'acquired' : 'conflict',
  } } };
});

return $input.all().map((item) => ({ json: {
  status: 'claim_conflict',
  dead_letter_id: item.json.dead_letter.dead_letter_id,
  message: 'The dead letter was already claimed or changed. No provider action was attempted.',
} }));

const originals = $('Restore Retry Claim').all();
return $input.all().map((item, index) => {
  const original = originals[index]?.json;
  if (!original) throw new Error(`Missing claimed recovery context ${index}`);
  return { json: { ...original, inquiry_claim_persisted: !item.json.error } };
});

const TEST_EMAIL = 'YOUR_CONTROLLED_TEST_EMAIL@example.com';
return $input.all().map((item) => {
  const data = item.json;
  const node = data.dead_letter.failed_node ?? '';
  const stage = data.dead_letter.error_stage;
  const payload = JSON.parse(data.dead_letter.original_payload_json || '{}');
  let action = 'manual_only';
  if (/slack/i.test(node)) action = 'slack_only';
  else if (/gmail|email/i.test(node)) action = 'gmail_only';
  else if (stage === 'crm') action = 'crm_reconcile';
  else if (stage === 'followup') action = 'followup_recheck';

  const customer = payload.customer ?? {};
  const slackText = [
    '*Recovered V4 construction inquiry alert*',
    `Inquiry: ${data.dead_letter.inquiry_id}`,
    `Correlation: ${data.dead_letter.correlation_id}`,
    `Customer: ${customer.name ?? 'Unknown'} (${customer.email ?? customer.phone ?? 'no contact method'})`,
    `Original failed execution: ${data.dead_letter.failed_execution_id}`,
    `Dead letter: ${data.dead_letter.dead_letter_id}`,
    `Recovery attempt: ${data.claim.attempt_count}`,
  ].join('\n');

  return { json: { ...data, recovery_action: {
    action,
    slack: { channel_id: 'CONFIGURE_SLACK_CHANNEL_ID', text: slackText },
    gmail: {
      to: TEST_EMAIL,
      subject: `Recovered inquiry acknowledgment: ${data.dead_letter.inquiry_id}`,
      body: `This is a controlled recovery message for ${customer.name ?? 'the customer'} and inquiry ${data.dead_letter.inquiry_id}. Original intended recipient: ${customer.email ?? 'unavailable'}.`,
    },
    crm_search: {
      filterGroups: [{ filters: [{ propertyName: 'construction_inquiry_id', operator: 'EQ', value: data.dead_letter.inquiry_id }] }],
      properties: ['dealname','dealstage','pipeline','construction_inquiry_id'],
      limit: 2,
    },
    followup_deal_id: data.inquiry?.hubspot_deal_id || null,
  } } };
});

return $input.all().map((item) => ({ json: { ...item.json, recovery_result: {
  action: item.json.recovery_action.action,
  outcome: 'manual_review',
  note: 'No implemented automatic action for this recovery boundary',
  provider_message_id: '',
  completed_at: new Date().toISOString(),
} } }));

const originals = $('Prepare Recovery Action').all();
return $input.all().map((item, index) => {
  const original = originals[index]?.json;
  if (!original) throw new Error(`Missing recovery-action context ${index}`);
  const action = original.recovery_action.action;
  const error = item.json.error?.message ?? item.json.error ?? null;
  let outcome = error ? 'retry_failed' : 'resolved';
  let note = error ? String(error) : `${action} completed successfully`;

  if (action === 'slack_only' && item.json.ok === false) {
    outcome = 'retry_failed'; note = String(item.json.error ?? 'Slack returned an unsuccessful response');
  }
  if (action === 'crm_reconcile' && !error) {
    const results = Array.isArray(item.json.results) ? item.json.results : [];
    if (results.length === 1) note = `Existing HubSpot Deal ${results[0].id} confirmed; no create repeated`;
    else { outcome = 'manual_review'; note = results.length === 0 ? 'No existing Deal found; creation requires reviewed recovery' : 'Multiple Deals found; manual reconciliation required'; }
  }
  if (action === 'followup_recheck' && !error) {
    const stage = item.json.properties?.dealstage ?? null;
    if (!stage) { outcome = 'manual_review'; note = 'Follow-up Deal stage unavailable'; }
    else if (stage === 'appointmentscheduled') { outcome = 'manual_review'; note = 'Deal remains New Inquiry; reviewed follow-up send is required'; }
    else note = `Follow-up suppressed because Deal stage is ${stage}`;
  }

  return { json: { ...original, recovery_result: {
    action, outcome, note,
    provider_message_id: String(item.json.ts ?? item.json.message?.ts ?? item.json.id ?? ''),
    completed_at: new Date().toISOString(),
  } } };
});

return $input.all().map((item) => {
  const data = item.json;
  const result = data.recovery_result;
  const attempts = data.claim.attempt_count;
  let deadLetterStatus = 'open';
  let inquiryStatus = 'pending_review';
  if (result.outcome === 'resolved') { deadLetterStatus = 'resolved'; inquiryStatus = 'resolved'; }
  else if (result.outcome === 'manual_review') { deadLetterStatus = 'manual_review'; inquiryStatus = 'manual_review'; }
  else if (attempts >= 3) { deadLetterStatus = 'manual_review'; inquiryStatus = 'attempt_limit_reached'; }

  return { json: { ...data, recovery_persistence: {
    dead_letter_status: deadLetterStatus,
    inquiry_status: inquiryStatus,
    attempt_count: attempts,
    last_attempt_at: data.claim.claimed_at,
    resolved_at: result.outcome === 'resolved' ? result.completed_at : '',
    resolution_note: result.note,
    processing_stage: result.outcome === 'resolved' ? 'reprocessing_resolved' : 'reprocessing_attention_required',
  } } };
});

const originals = $('Prepare Recovery Persistence').all();
return $input.all().map((item, index) => ({ json: {
  ...originals[index].json,
  dead_letter_persistence_ok: !item.json.error,
} }));

const originals = $('Restore After Dead Letter Resolution').all();
return $input.all().map((item, index) => ({ json: {
  ...originals[index].json,
  inquiry_persistence_ok: !item.json.error,
} }));

return $input.all().map((item) => ({ json: {
  status: item.json.recovery_persistence.inquiry_status,
  dead_letter_id: item.json.dead_letter.dead_letter_id,
  inquiry_id: item.json.dead_letter.inquiry_id,
  recovery_action: item.json.recovery_result.action,
  recovery_outcome: item.json.recovery_result.outcome,
  attempt_count: item.json.recovery_persistence.attempt_count,
  note: item.json.recovery_result.note,
  provider_message_id: item.json.recovery_result.provider_message_id || null,
} }));
